package com.cachefs.platform;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class CacheFsApplication {

    public static void main(String[] args) {
        SpringApplication.run(CacheFsApplication.class, args);
    }
}

package com.cachefs.platform.config;

import com.cachefs.platform.entity.CacheCluster;
import com.cachefs.platform.entity.User;
import com.cachefs.platform.mapper.CacheClusterMapper;
import com.cachefs.platform.mapper.UserMapper;
import java.time.LocalDateTime;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final CacheClusterMapper cacheClusterMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           CacheClusterMapper cacheClusterMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.cacheClusterMapper = cacheClusterMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        seedUser("admin", "admin123", "ADMIN");
        seedUser("user1", "user123", "USER");
        seedDefaultCluster();
    }

    private void seedUser(String username, String rawPassword, String role) {
        if (userMapper.countByUsername(username) > 0) {
            return;
        }
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());
        userMapper.insert(user);
    }

    private void seedDefaultCluster() {
        if (cacheClusterMapper.count() > 0) {
            return;
        }
        User admin = userMapper.findByUsername("admin");
        CacheCluster cluster = new CacheCluster();
        cluster.setName("默认缓存集群");
        cluster.setDescription("系统默认缓存集群");
        cluster.setRegion("cn-hangzhou");
        cluster.setStatus("ACTIVE");
        cluster.setCreatorId(admin.getId());
        cluster.setCreatedAt(LocalDateTime.now());
        cacheClusterMapper.insert(cluster);
    }
}

package com.cachefs.platform.config;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import java.nio.charset.StandardCharsets;
import java.util.Date;
import javax.crypto.SecretKey;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.expiration}")
    private long expiration;

    private SecretKey signingKey() {
        return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public String generateToken(String username, String role) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expiration * 1000L);
        return Jwts.builder()
                .setSubject(username)
                .claim("role", role)
                .setIssuedAt(now)
                .setExpiration(expiry)
                .signWith(signingKey(), SignatureAlgorithm.HS256)
                .compact();
    }

    public boolean validateToken(String token) {
        try {
            parseClaims(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public String getUsername(String token) {
        return parseClaims(token).getSubject();
    }

    public String getRole(String token) {
        return parseClaims(token).get("role", String.class);
    }

    private Claims parseClaims(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(signingKey())
                .build()
                .parseClaimsJws(token)
                .getBody();
    }
}

package com.cachefs.platform.config;

import com.cachefs.platform.filter.JwtAuthFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http.csrf(csrf -> csrf.disable())
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/**").permitAll()
                        .anyRequest().authenticated())
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}

package com.cachefs.platform.controller;

import com.cachefs.platform.dto.ApiResponse;
import com.cachefs.platform.dto.LoginRequest;
import com.cachefs.platform.dto.LoginResponse;
import com.cachefs.platform.service.AuthService;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ApiResponse<LoginResponse> login(@RequestBody LoginRequest request) {
        LoginResponse result = authService.login(request.getUsername(), request.getPassword());
        if (result == null) {
            return ApiResponse.error(401, "用户名或密码错误");
        }
        return ApiResponse.success("登录成功", result);
    }
}

package com.cachefs.platform.controller;

import com.cachefs.platform.dto.ApiResponse;
import com.cachefs.platform.dto.CreateClusterRequest;
import com.cachefs.platform.entity.CacheCluster;
import com.cachefs.platform.service.ClusterService;
import java.util.List;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/clusters")
public class ClusterController {

    private final ClusterService clusterService;

    public ClusterController(ClusterService clusterService) {
        this.clusterService = clusterService;
    }

    @PostMapping
    public ApiResponse<CacheCluster> createCluster(@RequestBody CreateClusterRequest request,
                                                   Authentication authentication) {
        boolean isAdmin = authentication.getAuthorities().stream()
                .anyMatch(authority -> "ROLE_ADMIN".equals(authority.getAuthority()));
        if (!isAdmin) {
            return ApiResponse.error(403, "权限不足");
        }
        CacheCluster cluster = clusterService.createCluster(request, authentication.getName());
        return ApiResponse.success("创建成功", cluster);
    }

    @GetMapping
    public ApiResponse<List<CacheCluster>> listClusters() {
        return ApiResponse.success(clusterService.listClusters());
    }

    @GetMapping("/{id}")
    public ApiResponse<CacheCluster> getCluster(@PathVariable("id") Long id) {
        CacheCluster cluster = clusterService.getCluster(id);
        if (cluster == null) {
            return ApiResponse.error(404, "集群不存在");
        }
        return ApiResponse.success(cluster);
    }
}

package com.cachefs.platform.controller;

import com.cachefs.platform.dto.ApiResponse;
import com.cachefs.platform.dto.CreateMountRequest;
import com.cachefs.platform.entity.CacheMount;
import com.cachefs.platform.entity.MountLog;
import com.cachefs.platform.service.MountService;
import java.util.List;
import java.util.Map;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public class MountController {

    private final MountService mountService;

    public MountController(MountService mountService) {
        this.mountService = mountService;
    }

    @PostMapping("/clusters/{clusterId}/mounts")
    public ApiResponse<CacheMount> createMount(@PathVariable("clusterId") Long clusterId,
                                               @RequestBody CreateMountRequest request,
                                               Authentication authentication) {
        CacheMount mount = mountService.createMount(clusterId, request, authentication.getName());
        return ApiResponse.success("创建成功", mount);
    }

    @GetMapping("/clusters/{clusterId}/mounts")
    public ApiResponse<List<CacheMount>> listMounts(@PathVariable("clusterId") Long clusterId) {
        return ApiResponse.success(mountService.listMountsByCluster(clusterId));
    }

    @GetMapping("/mounts/{id}")
    public ApiResponse<CacheMount> getMount(@PathVariable("id") Long id) {
        CacheMount mount = mountService.getMount(id);
        if (mount == null) {
            return ApiResponse.error(404, "挂载配置不存在");
        }
        return ApiResponse.success(mount);
    }

    @PostMapping("/mounts/{id}/execute")
    public ApiResponse<Map<String, Object>> executeMount(@PathVariable("id") Long id,
                                                         Authentication authentication) {
        if (mountService.getMount(id) == null) {
            return ApiResponse.error(404, "挂载配置不存在");
        }
        Map<String, Object> result = mountService.executeMount(id, authentication.getName());
        return ApiResponse.success("挂载执行完成", result);
    }

    @PostMapping("/mounts/{id}/unmount")
    public ApiResponse<Map<String, Object>> executeUnmount(@PathVariable("id") Long id,
                                                           Authentication authentication) {
        if (mountService.getMount(id) == null) {
            return ApiResponse.error(404, "挂载配置不存在");
        }
        Map<String, Object> result = mountService.executeUnmount(id, authentication.getName());
        return ApiResponse.success("卸载执行完成", result);
    }

    @GetMapping("/mounts/{id}/logs")
    public ApiResponse<List<MountLog>> getLogs(@PathVariable("id") Long id) {
        return ApiResponse.success(mountService.getLogs(id));
    }
}

package com.cachefs.platform.dto;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class ApiResponse<T> {
    private int code;
    private String message;
    private T data;

    public static <T> ApiResponse<T> success(T data) {
        return new ApiResponse<>(200, "success", data);
    }

    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(200, message, data);
    }

    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }
}

